'use strict';
const NETWORK_UI14={uxAreas11,managementView,bind,render};
let networkTab14='panel',networkPeriod14=1,networkCity14='all',networkSort14='profit',networkDirection14='asc',networkFilter14='all',networkSelection14=[],networkDraft14={kind:'price',delta:5,key:'machine',model:'premium',cap:500000,reserve:3};
function networkMetricText14(key,value){return value===null?'—':['cash','profit'].includes(key)?money(value):key==='reserve'?number(value,1)+' týdnů':key==='quality'?number(value,1)+' / 100':number(value);}
function networkOpen14(tab='panel'){networkTab14=tab;const body=tab==='panel'?networkPanelHtml14():tab==='compare'?networkComparisonHtml14():tab==='bulk'?networkBulkHtml14():networkHistoryHtml14();show(`<div class="network-title14"><span class="eyelabel">ŘÍZENÍ VLASTNÍ SÍTĚ</span><h2>Můj řídicí panel</h2></div><div class="network-tabs14" role="tablist" aria-label="Řízení sítě">${[['panel','Můj panel'],['compare','Porovnání poboček'],['bulk','Hromadné změny'],['history','Provedené změny']].map(([key,label])=>`<button class="soft" id="networkTab-${key}" role="tab" aria-selected="${tab===key}" tabindex="${tab===key?0:-1}" aria-controls="networkBody14" data-network-tab14="${key}">${label}</button>`).join('')}</div><section id="networkBody14" role="tabpanel" aria-labelledby="networkTab-${tab}">${body}</section>`);const tabs=[...el('modalContent').querySelectorAll('[data-network-tab14]')];tabs.forEach((b,i)=>{b.onclick=()=>networkOpen14(b.dataset.networkTab14);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const index=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;networkOpen14(tabs[index].dataset.networkTab14);el('networkTab-'+tabs[index].dataset.networkTab14).focus();};});networkBind14();}
function networkPanelHtml14(){const p=networkPanel14();return `<div class="network-toolbar14"><p>${p.week?'Uzavřený T'+p.week+' · hotovost a rezerva podle nynější firmy.':'První výsledky přibudou po odehraném týdnu.'}</p><button class="soft" id="networkCustomize14">Upravit můj panel</button></div><div class="network-metrics14">${state.network14.metrics.map(key=>`<article class="card"><small>${NETWORK_METRICS14[key]}</small><strong>${networkMetricText14(key,p.metrics[key])}</strong>${key==='profit'?'<small>Celá firma po nákladech a dani</small>':key==='reserve'?'<small>Fixní provoz, marketing, projekty a blízké faktury</small>':''}</article>`).join('')||'<p class="sub">Připni si ukazatele přes Upravit můj panel.</p>'}</div><h3>Připnuté kavárny</h3><div class="network-pins14">${p.pins.map(r=>`<article class="card"><div class="card-head"><h3>${esc(r.name)}</h3><button class="quiet" data-network-pin14="${r.id}" aria-label="Odepnout ${esc(r.name)}">Odepnout</button></div><p class="sub">${esc(r.city)} · ${r.current?'Vlastní provoz':'Provoz už není ve vlastní síti'}</p>${rows([['Výsledek týdne',r.values.profit===null?'Zatím bez výsledku':money(r.values.profit)],['Obsloužení hosté',r.values.served===null?'—':number(r.values.served)]])}${r.current?`<button class="soft" data-network-detail14="${r.id}">Provozní rozbor</button>`:''}</article>`).join('')||empty('Připni kavárny v porovnání poboček nebo v nastavení panelu.')}</div><h3>Sledované problémy</h3><p class="sub">${state.network14.issues.map(k=>NETWORK_ISSUES14[k]).join(' · ')||'Žádný typ problému není připnutý.'}</p>${p.issues.slice(0,12).map(x=>`<article class="news network-issue14"><div><strong>${esc(x.title)}</strong><p>T${x.week} · ${esc(x.text)}</p></div><button class="soft" data-network-detail14="${x.id}">Prověřit provoz</button></article>`).join('')||empty(p.week?'Ve sledovaných kategoriích není zaznamenaný problém.':'Odehraj první týden pro skutečné provozní problémy.')}${p.issues.length>12?'<button class="soft" id="networkAllIssues14">Porovnat všechny pobočky</button>':''}`;}
function networkCustomize14(){show(`<h2>Upravit můj řídicí panel</h2><p>Vyber, co chceš při řízení sledovat. Nastavení se uloží s touto firmou.</p><h3>Ukazatele</h3><div class="network-options14">${Object.entries(NETWORK_METRICS14).map(([key,label])=>`<label><input type="checkbox" data-network-metric14="${key}" ${state.network14.metrics.includes(key)?'checked':''}> ${label}</label>`).join('')}</div><h3>Problémy</h3><div class="network-options14">${Object.entries(NETWORK_ISSUES14).map(([key,label])=>`<label><input type="checkbox" data-network-issue14="${key}" ${state.network14.issues.includes(key)?'checked':''}> ${label}</label>`).join('')}</div><h3>Připnuté kavárny · nejvýše osm</h3><div class="network-options14">${state.stores.filter(s=>!s.franchise).map(s=>`<label><input type="checkbox" data-network-custom-pin14="${s.id}" ${state.network14.pins.includes(s.id)?'checked':''}> ${esc(loc(s.id).city+' · '+loc(s.id).name)}</label>`).join('')||'<p>Zatím nemáš vlastní kavárnu.</p>'}</div><div class="actions"><button class="primary" id="networkSavePanel14">Uložit panel</button><button class="soft" id="networkCancelPanel14">Zrušit</button></div>`);el('networkCancelPanel14').onclick=()=>networkOpen14('panel');el('networkSavePanel14').onclick=()=>{const selected=attribute=>[...el('modalContent').querySelectorAll('['+attribute+']:checked')].map(n=>n.getAttribute(attribute));const data={metrics:selected('data-network-metric14'),issues:selected('data-network-issue14'),pins:selected('data-network-custom-pin14')};if(act(()=>setNetworkPanel14(data),'Panel uložen.'))networkOpen14('panel');};}
function networkComparisonHtml14(){const r=networkComparison14(networkPeriod14,networkCity14,networkSort14,networkDirection14,networkFilter14);return `<div class="fields network-filters14">${field('Období',`<select id="networkPeriod14">${[1,4,13].map(n=>option(n,n+' '+(n===1?'uzavřený týden':n===4?'uzavřené týdny':'uzavřených týdnů'),networkPeriod14)).join('')}</select>`)}${field('Město',`<select id="networkCity14">${option('all','Všechna města',networkCity14)}${CITIES.map(c=>option(c.name,c.name,networkCity14)).join('')}</select>`)}${field('Pobočky',`<select id="networkFilter14">${[['all','Vlastní i historické'],['current','Současné vlastní'],['loss','Ztrátové za období'],['historical','Už nejsou ve vlastní síti']].map(([key,label])=>option(key,label,networkFilter14)).join('')}</select>`)}${field('Seřadit podle',`<select id="networkSort14">${[['profit','Výsledek'],['served','Obsloužení hosté'],['lossRate','Podíl neobsloužených'],['wait','Čekání'],['quality','Kvalita'],['trend','Vývoj výsledku'],['name','Název']].map(([key,label])=>option(key,label,networkSort14)).join('')}</select>`)}${field('Pořadí',`<select id="networkDirection14">${option('asc','Od nejnižší hodnoty',networkDirection14)}${option('desc','Od nejvyšší hodnoty',networkDirection14)}</select>`)}</div><p class="sub">${r.end?'T'+Math.max(1,r.start)+'–'+r.end+' · v archivu '+r.count+' z '+r.weeks+' týdnů.':'Zatím žádný uzavřený týden.'} Každá pobočka uvádí svůj počet skutečných výsledků. Vývoj porovnává průměr na skutečně zaznamenaný týden s předchozím stejně dlouhým obdobím.</p><p>Výsledek vybraných provozů: <strong>${r.totals.profit===null?'—':money(r.totals.profit)}</strong> · obsloužení hosté <strong>${r.totals.served===null?'—':number(r.totals.served)}</strong>.</p><div class="network-comparison14">${r.rows.map(row=>`<article class="network-branch14"><div class="network-branch-heading14"><label class="network-select14"><input type="checkbox" data-network-select14="${row.id}" ${networkSelection14.includes(row.id)?'checked':''} ${!row.current?'disabled':''} aria-label="Vybrat ${esc(row.name)}"><strong>${esc(row.name)}</strong></label><small>${esc(row.city)} · ${row.samples}/${r.weeks} týdnů · ${esc(row.owner)}${!row.current?' · historický provoz':''}</small></div><dl><div><dt>Výsledek provozu</dt><dd class="${row.values.profit<0?'bad':''}">${row.values.profit===null?'—':money(row.values.profit)}</dd></div><div><dt>Hosté / neobsloužení</dt><dd>${row.values.served===null?'—':number(row.values.served)} / ${row.values.lost===null?'—':number(row.values.lost)}</dd></div><div><dt>Čekání / kvalita</dt><dd>${row.values.wait===null?'—':number(row.values.wait,1)+' min'} / ${row.values.quality===null?'—':number(row.values.quality,1)}</dd></div><div><dt>Vývoj / skutečný týden</dt><dd>${row.trend===null?'Bez srovnání':(row.trend>0?'+':'')+money(row.trend)}</dd></div></dl><div class="network-branch-actions14">${row.current?`<button class="soft" data-network-detail14="${row.id}">Rozbor</button><button class="quiet" data-network-pin14="${row.id}">${row.pinned?'Odepnout':'Připnout'}</button>`:''}</div></article>`).join('')||empty('Žádná pobočka neodpovídá filtru.')} </div><div class="actions network-selection14"><button class="soft" id="networkSelectVisible14">Vybrat současné ve filtru</button><button class="quiet" id="networkClearSelection14">Zrušit výběr</button><button class="primary" id="networkFromCompare14">Změnit vybrané (${networkSelection14.filter(id=>state.stores.some(s=>s.id===id&&!s.franchise)).length})</button></div><p class="sub">Výsledky poboček zahrnují místní náklady. Centrála, výroba, daně a další společné náklady zůstávají ve výsledku celé firmy. Franšízy mají samostatného provozovatele a nejsou součástí těchto hromadných změn.</p>`;}
function networkBulkHtml14(){networkSelection14=networkSelection14.filter(id=>state.stores.some(s=>s.id===id&&!s.franchise));const d=networkDraft14;return `<h3>Hromadná změna vybraných kaváren</h3><p>Nejprve prověř celý zásah, potom potvrď přesnou nabídku. Každá pobočka má vlastní cenu, výkup a odhad provozu.</p><div class="network-options14">${state.stores.filter(s=>!s.franchise).map(s=>`<label><input type="checkbox" data-network-bulk-store14="${s.id}" ${networkSelection14.includes(s.id)?'checked':''}> ${esc(loc(s.id).city+' · '+loc(s.id).name)}</label>`).join('')||'<p>Nejdřív otevři vlastní kavárnu.</p>'}</div><div class="fields">${field('Zásah',`<select id="networkKind14">${[['price','Změna cen kávového menu'],['equipment','Výměna modelu vybavení'],['service','Servis jednoho typu zařízení']].map(([key,label])=>option(key,label,d.kind)).join('')}</select>`)}${field('Maximální celková platba / Kč',input('networkCap14',d.cap,0,10000000,500))}${field('Chráněná rezerva / týdny',input('networkReserve14',d.reserve,1,8,1))}</div><div id="networkPriceFields14" class="fields" ${d.kind!=='price'?'hidden':''}>${field('Změna všech cen kávy',`<select id="networkDelta14">${option(5,'+5 Kč',d.delta)}${option(-5,'−5 Kč',d.delta)}</select>`)}</div><div id="networkEquipmentFields14" class="fields" ${d.kind==='price'?'hidden':''}>${field('Zařízení',`<select id="networkKey14">${Object.keys(EQUIPMENT_MODELS5).map(key=>option(key,EQUIPMENT[key].name,d.key)).join('')}</select>`)}<div id="networkModelField14" ${d.kind==='service'?'hidden':''}>${field('Model',`<select id="networkModel14">${Object.entries(EQUIPMENT_MODELS5[d.key]).map(([key,cfg])=>option(key,cfg.name,d.model)).join('')}</select>`)}</div></div><div class="actions"><button class="primary" id="networkQuote14" ${!state.stores.some(s=>!s.franchise)?'disabled':''}>Prověřit celý zásah</button><button class="soft" id="networkBackCompare14">Zpět k porovnání</button></div>`;}
function networkReadDraft14(){const kind=el('networkKind14').value;networkSelection14=[...el('modalContent').querySelectorAll('[data-network-bulk-store14]:checked')].map(n=>n.dataset.networkBulkStore14);networkDraft14={kind,delta:Number(el('networkDelta14').value),key:el('networkKey14').value,model:el('networkModel14').value,cap:Number(el('networkCap14').value),reserve:Number(el('networkReserve14').value)};return networkDraft14;}
function networkQuoteUI14(){try{const d=networkReadDraft14(),data=d.kind==='price'?{delta:d.delta}:d.kind==='equipment'?{key:d.key,model:d.model}:{key:d.key},q=networkBulkQuote14(networkSelection14,d.kind,data,d.cap,d.reserve);show(`<span class="eyelabel">NÁHLED · NIC ZATÍM NEBYLO ZMĚNĚNO</span><h2>Kavárny: ${q.rows.filter(r=>r.changed).length} · ${q.kind==='price'?'ceny menu':q.kind==='equipment'?'vybavení':'servis'}</h2>${rows([['Nové vybavení / servis',money(q.purchases)],['Výkup původního vybavení',money(q.credit)],['Celková změna hotovosti',money(-q.cost)],['Hotovost po provedení',money(q.cashAfter)],['Změna týdenních závazků',money(q.weeklyChange)],['Chráněná rezerva',money(q.protectedCash)],['Schválený strop',money(q.cap)]])}${q.warnings.map(s=>`<p class="warning">${esc(s)}</p>`).join('')}<div class="network-quote14">${q.rows.map(r=>`<article class="card"><h3>${esc(r.name)} · ${esc(r.city)}</h3><p>${esc(r.label)} · ${r.changed?'Provede se':'Už platí, bez platby'}</p>${rows([['Platba',money(r.cost)+(r.credit?' · výkup '+money(r.credit):'')],['Odhad výsledku před / po',money(r.before.profit)+' / '+(r.after?money(r.after.profit):'Nelze provést')],['Odhad hostů před / po',r.before.served+' / '+(r.after?r.after.served:'—')],['Hosté bez kávy před / po',r.before.stockLost+' / '+(r.after?r.after.stockLost:'—')]])}</article>`).join('')}</div><p class="sub">${esc(q.assumption)}</p><p class="sub">${q.kind==='price'?'Automatické vedení může ceny v dalším týdnu upravit podle povoleného mandátu.':''} Změní-li se firma, cenu nejprve znovu prověř. Při neplatné nabídce se neprovede žádná část.</p><div class="actions"><button class="primary" id="networkConfirm14" ${!q.safe?'disabled':''}>Provést celý zásah</button><button class="soft" id="networkCancelQuote14">Zpět bez změny</button></div>`);el('networkCancelQuote14').onclick=()=>networkOpen14('bulk');el('networkConfirm14').onclick=()=>{const result=act(()=>applyNetworkBulk14(q.ids,q.kind,q.data,q.cap,q.reserve,q),'Hromadná změna provedena.');if(result)networkOpen14('history');};}catch(e){toast(e.message);}}
function networkHistoryHtml14(){return `<h3>Provedené hromadné změny</h3><p class="sub">Odhad vznikl při potvrzení. Skutečný výsledek se zapíše po uzavření stejného týdne, včetně všech ostatních změn provozu. Historie obsahuje posledních 26 zásahů.</p>${state.network14.history.slice().reverse().map(r=>`<details class="network-history14"><summary>T${r.week} · ${({price:'Ceny menu',equipment:'Vybavení',service:'Servis'})[r.kind]} · Kavárny: ${r.rows.filter(x=>x.changed).length} · ${money(r.cost)}</summary>${r.rows.map(x=>`<article><strong>${esc(x.name)} · ${x.changed?'provedeno':'beze změny'}</strong>${rows([['Platba',money(x.cost)],['Odhad před / po',money(x.before.profit)+' / '+money(x.expected.profit)],['Skutečný výsledek T'+r.week,x.actual?(x.actual.unavailable?'Provoz již nebyl dostupný':money(x.actual.profit)+' · '+x.actual.served+' hostů'):'Čeká na uzavření týdne']])}</article>`).join('')}</details>`).join('')||empty('Zatím žádná provedená hromadná změna.')}`;}
function networkDetail14(id){const origin=networkTab14;tnDiagnosisDialog7(id);if(!el('modalContent').querySelector('h2'))return;const b=document.createElement('button');b.className='soft';b.id='networkDetailBack14';b.textContent='Zpět na můj panel';b.onclick=()=>networkOpen14(origin);el('modalContent').querySelector('h2').after(b);}
function networkBind14(){if(el('networkCustomize14'))el('networkCustomize14').onclick=networkCustomize14;on('[data-network-pin14]',b=>{const id=b.dataset.networkPin14;if(act(()=>networkPin14(id)))networkOpen14(networkTab14);});on('[data-network-detail14]',b=>networkDetail14(b.dataset.networkDetail14));for(const [id,key] of [['networkPeriod14','period'],['networkCity14','city'],['networkSort14','sort'],['networkDirection14','direction'],['networkFilter14','filter']])if(el(id))el(id).onchange=()=>{const value=el(id).value;if(key==='period')networkPeriod14=Number(value);if(key==='city')networkCity14=value;if(key==='sort')networkSort14=value;if(key==='direction')networkDirection14=value;if(key==='filter')networkFilter14=value;networkOpen14('compare');};on('[data-network-select14]',b=>{const id=b.dataset.networkSelect14;networkSelection14=b.checked?[...new Set([...networkSelection14,id])]:networkSelection14.filter(k=>k!==id);el('networkFromCompare14').textContent='Změnit vybrané ('+networkSelection14.length+')';},'change');if(el('networkSelectVisible14'))el('networkSelectVisible14').onclick=()=>{networkSelection14=[...new Set([...networkSelection14,...networkComparison14(networkPeriod14,networkCity14,networkSort14,networkDirection14,networkFilter14).rows.filter(r=>r.current).map(r=>r.id)])];networkOpen14('compare');};if(el('networkClearSelection14'))el('networkClearSelection14').onclick=()=>{networkSelection14=[];networkOpen14('compare');};if(el('networkFromCompare14'))el('networkFromCompare14').onclick=()=>networkOpen14('bulk');if(el('networkAllIssues14'))el('networkAllIssues14').onclick=()=>networkOpen14('compare');if(el('networkBackCompare14'))el('networkBackCompare14').onclick=()=>networkOpen14('compare');if(el('networkKind14'))el('networkKind14').onchange=()=>{networkReadDraft14();networkOpen14('bulk');};if(el('networkKey14'))el('networkKey14').onchange=()=>{const d=networkReadDraft14();if(!EQUIPMENT_MODELS5[d.key][d.model])d.model=Object.keys(EQUIPMENT_MODELS5[d.key]).at(-1);networkOpen14('bulk');};if(el('networkQuote14'))el('networkQuote14').onclick=networkQuoteUI14;}
uxAreas11=function(){NETWORK_UI14.uxAreas11();const b=document.createElement('button');b.className='primary';b.id='networkOpen14';b.textContent='Můj panel a pobočky';b.onclick=()=>networkOpen14();const group=el('modalContent').querySelector('[data-ux-area-group11]');if(group)group.querySelector('h3').after(b);else el('modalContent').querySelector('.ux-utilities11').prepend(b);const search=el('uxAreaQuery11'),input=search.oninput,key=search.onkeydown;search.oninput=e=>{input(e);const tokens=uxNormalize10(search.value).split(/\s+/).filter(Boolean);b.hidden=!tokens.every(t=>uxNormalize10('Můj řídicí panel pobočky porovnání hromadné změny').includes(t));if(group)group.hidden=![...group.querySelectorAll('button')].some(n=>!n.hidden);if(!b.hidden)el('uxAreaEmpty11').hidden=true;};search.onkeydown=e=>{if(e.key==='Enter'&&!b.hidden&&search.value.trim()&&!el('modalContent').querySelector('[data-view]:not([hidden]),[data-ux-shortcut11]')){e.preventDefault();b.click();}else key(e);};};
managementView=function(){return `<section class="card network-entry14"><h2>Můj řídicí panel</h2><p>Připnuté ukazatele a kavárny, porovnání výsledků a společné změny s náhledem ceny.</p><div class="actions"><button class="primary" id="networkManage14">Otevřít můj panel</button><button class="soft" id="networkCompare14">Porovnat pobočky</button></div></section>`+NETWORK_UI14.managementView();};
bind=function(){NETWORK_UI14.bind();if(el('networkManage14'))el('networkManage14').onclick=()=>networkOpen14();if(el('networkCompare14'))el('networkCompare14').onclick=()=>networkOpen14('compare');};
render=function(...a){NETWORK_UI14.render(...a);if(el('uxAll11'))el('uxAll11').onclick=uxAreas11;if(gameMode6&&state.stores.some(s=>!s.franchise)&&el('gameMission6')&&!el('networkMission14')){const b=document.createElement('button');b.id='networkMission14';b.textContent='Můj panel a pobočky';b.onclick=()=>networkOpen14();el('gameMission6').append(b);}};render();
